use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Sets `out_vec[i] = op(out_vec[i], in_vec[i])` for each index `i` in both"] # [doc = " slices. The slices must have the same length."] # [doc = ""] # [doc = " Returns true if at least one bit in `out_vec` was changed."] # [doc = ""] # [doc = " ## Warning"] # [doc = " Some bitwise operations (e.g. union-not, xor) can set output bits that were"] # [doc = " unset in in both inputs. If this happens in the last word/chunk of a bitset,"] # [doc = " it can cause the bitset to contain out-of-domain values, which need to"] # [doc = " be cleared with `clear_excess_bits_in_final_word`. This also makes the"] # [doc = " \"changed\" return value unreliable, because the change might have only"] # [doc = " affected excess bits."] # [inline] fn bitwise < Op > (out_vec : & mut [Word] , in_vec : & [Word] , op : Op) -> bool where Op : Fn (Word , Word) -> Word , { assert_eq ! (out_vec . len () , in_vec . len ()) ; let mut changed = 0 ; for (out_elem , in_elem) in iter :: zip (out_vec , in_vec) { let old_val = * out_elem ; let new_val = op (old_val , * in_elem) ; * out_elem = new_val ; changed |= old_val ^ new_val ; } changed != 0 }